#include <queue>
#include <iostream>

int main() {
    std::priority_queue<int> pq;
    pq.push(10); 
    pq.push(20);

    if (!pq.empty()) {
        // Step 1: Access (O(1))
        int value = pq.top(); 
        std::cout << "Retrieved value: " << value << std::endl;

        // Step 2: Remove (O(log N))
        pq.pop(); 
    }

    // WARNING: Cannot do this: int x = pq.pop();
}
